        "final_answer": str(quotient.numerator),
        "evidence": {
            "numerator": numerator,
            "denominator": denominator,
            "exact_quotient": str(quotient),
            "is_integer": is_integer,
            "verification_quotient_times_denominator_equals_numerator": check,
